package com.ruoyi.web.controller.meeting;
import java.util.Map;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import com.ruoyi.common.core.controller.BaseController;import com.ruoyi.common.core.domain.AjaxResult;import com.ruoyi.system.service.IYcMealService;
@RestController@RequestMapping("/meeting/meal")public class YcMealController extends BaseController{@Autowired private IYcMealService service;@PreAuthorize("@ss.hasPermi('meeting:meal:redeem')")@PostMapping("/redeem")public AjaxResult redeem(@RequestBody Map<String,Object> body){return success(service.redeem(str(body.get("credential")),str(body.get("activityId")),str(body.get("checkpoint")),getUsername(),str(body.get("deviceId")),str(body.get("idempotencyKey"))));}@PreAuthorize("@ss.hasPermi('meeting:meal:redeem')")@PostMapping("/revoke")public AjaxResult revoke(@RequestBody Map<String,Object> body){return success(service.revoke(Long.valueOf(str(body.get("couponId"))),str(body.get("checkpoint")),getUsername(),str(body.get("deviceId")),str(body.get("idempotencyKey"))));}@PreAuthorize("@ss.hasPermi('meeting:meal:issue')")@PostMapping("/issue")public AjaxResult issue(@RequestBody Map<String,Object> body){return toAjax(service.issue(Long.valueOf(str(body.get("activityId"))),Long.valueOf(str(body.get("ticketId"))),Long.valueOf(str(body.get("applyOrderId"))),getUsername()));}private String str(Object v){return v==null?"":String.valueOf(v);}}
